import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'

import type { TraceLinkParams } from 'lib/components/ViewTraceButton/traceUrl'
import { FEATURE_FLAGS } from 'lib/constants'
import { type FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDialogLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    dialogEnabled: boolean
    isOpen: boolean
    trace: TraceLinkParams | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDialogLogicActions {
    locationChanged: ({
        method,
        pathname,
        search,
        searchParams,
        hash,
        hashParams,
        initial,
        url,
        routerState,
    }: LocationChangedPayload) => {
        hash: string
        hashParams: Record<string, any>
        initial: boolean
        method: 'POP' | 'PUSH' | 'REPLACE'
        pathname: string
        routerState: Record<string, any>
        search: string
        searchParams: Record<string, any>
        url: string
    } // router
    closeTraceDialog: () => {
        value: true
    }
    openTraceDialog: (trace: TraceLinkParams) => {
        trace: TraceLinkParams
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceDialogLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        dialogEnabled: (featureFlags: FeatureFlagsSet) => boolean
    }
}

export type traceDialogLogicType = MakeLogicType<
    traceDialogLogicValues,
    traceDialogLogicActions,
    Record<string, any>,
    traceDialogLogicMeta
>

export const traceDialogLogic = kea<traceDialogLogicType>([
    path(['products', 'tracing', 'frontend', 'components', 'TraceDialog', 'traceDialogLogic']),
    connect(() => ({
        actions: [router, ['locationChanged']],
        values: [featureFlagLogic, ['featureFlags']],
    })),
    actions({
        openTraceDialog: (trace: TraceLinkParams) => ({ trace }),
        closeTraceDialog: true,
    }),
    reducers({
        isOpen: [
            false,
            {
                openTraceDialog: () => true,
                closeTraceDialog: () => false,
            },
        ],
        // Survives close: useKeepMountedWhileOpen keeps the dialog rendered through its exit
        // animation, and clearing the trace then would flash an empty dialog.
        trace: [
            null as TraceLinkParams | null,
            {
                openTraceDialog: (_, { trace }) => trace,
            },
        ],
    }),
    selectors({
        // Every entry point checks this one place, so the flag cannot open the dialog from some
        // links and not others.
        dialogEnabled: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !!featureFlags[FEATURE_FLAGS.TRACING_TRACE_DIALOG],
        ],
    }),
    listeners(({ values, actions, cache }) => ({
        locationChanged: ({ pathname }) => {
            // Query and hash changes fire locationChanged too, so only a new pathname closes the dialog.
            if (pathname === cache.lastPathname) {
                return
            }
            cache.lastPathname = pathname
            if (values.isOpen) {
                actions.closeTraceDialog()
            }
        },
    })),
    afterMount(({ cache }) => {
        cache.lastPathname = router.values.location.pathname
    }),
])
